const items = [];
const sources = $('Remove Duplicates (seen before)').all();
const all = $input.all();
for (let idx = 0; idx < all.length; idx++) {
  const item = all[idx];
  const src = sources[idx] ? sources[idx].json : {};
  let raw = (item.json.output && item.json.output[0] && item.json.output[0].content && item.json.output[0].content[0] && item.json.output[0].content[0].text) || (item.json.content && item.json.content[0] && item.json.content[0].text) || '';
  raw = raw.replace(/```json|```/g, '').trim();
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = { is_relevant: false };
  }
  items.push({
    json: {
      ...parsed,
      source_title: src.title || '',
      source_link: src.link || ''
    }
  });
}
return items;

const nseList = $('Get NSE List (once per run)').all().map(i => i.json);
const results = [];
for (const item of $input.all()) {
  const ai = item.json;
  if (!ai.is_relevant) continue;
  const guess = (ai.nse_symbol_guess || '').toString().toUpperCase().trim();
  const nameGuess = (ai.company_name || '').toString().toLowerCase().trim();
  let match = nseList.find(r => (r.SYMBOL || '').toString().toUpperCase().trim() === guess);
  if (!match && nameGuess) {
    const firstWord = nameGuess.split(' ')[0];
    match = nseList.find(r => (r['NAME OF COMPANY'] || '').toString().toLowerCase().includes(firstWord));
  }
  if (!match) continue;
  results.push({
    json: {
      company_name: ai.company_name || match['NAME OF COMPANY'],
      symbol: match.SYMBOL,
      summary: ai.summary || '',
      impact: ai.impact || 'Neutral',
      short_term_impact: ai.impact || 'Neutral',
      long_term_impact: ai.impact || 'Neutral',
      confidence: ai.confidence || 'N/A',
      source_link: ai.source_link || '',
      created_at: new Date().toISOString()
    }
  });
}
return results;

const results = [];
for (const item of $input.all()) {
  const d = item.json;
  const emoji = d.impact === 'Positive' ? '\ud83d\udfe2' : d.impact === 'Negative' ? '\ud83d\udd34' : '\ud83d\udfe1';
  const readMore = d.source_link ? `\n[Read more](${d.source_link})` : '';
  const msg = `${emoji} *${d.company_name}* (${d.symbol})\n${d.summary}\nImpact: *${d.impact}* (confidence: ${d.confidence})${readMore}`;
  results.push({ json: { ...d, message: msg } });
}
return results;

