).toLowerCase().trim();

if (!query) return [];

const rows = $input.all();

const filtered = rows.map(item => {
    const row = item.json;
    const name = String(row["NAME OF COMPANY"] || "").toLowerCase();
    const symbol = String(row["SYMBOL"] || "").toLowerCase();

    let score = 0;
    if (symbol === query) score += 100;
    else if (symbol.startsWith(query)) score += 50;
    else if (symbol.includes(query)) score += 20;

    if (name === query) score += 80;
    else if (name.startsWith(query)) score += 40;
    else if (name.includes(query)) score += 10;

    return { item, score };
}).filter(x => x.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 5)
  .map(x => x.item);

