const meta = result.meta || {};
const quote = result.indicators?.quote?.[0] || {};

// Extract live fields from CORRECT v8 paths
const price = meta.regularMarketPrice;
const prevClose = meta.chartPreviousClose;
const open = quote.open?.[0];           // open is inside indicators array
const dayHigh = meta.regularMarketDayHigh;
const dayLow = meta.regularMarketDayLow;
const high52 = meta.fiftyTwoWeekHigh;
const low52 = meta.fiftyTwoWeekLow;

// Calculate change percent from live price & prev close
