if (price !== undefined && prevClose !== undefined && prevClose !== 0) {
  changePct = ((price - prevClose) / prevClose) * 100;
} else {
  changePct = sheet["Percentage Change"];
}

// Helper: use Yahoo value if it exists and is a number, else fallback to sheet
const pick = (live, sheetVal) => (live !== undefined && live !== null && !isNaN(live)) ? live : sheetVal;

return [{
  json: {
    symbol: sheet.SYMBOL,
    company_name: sheet["NAME OF COMPANY"],
    sector: sheet.Sector,

    // Live from Yahoo v8 chart
    price: pick(price, sheet.Price),
    open: pick(open, sheet.Open),
    previous_close: pick(prevClose, sheet["Previous Close"]),
    change_percent: changePct,

    // Sheet data for rest
