const html = $input.first().json.data; // adjust field name to match your HTTP node's output

// Match each futures row: <a title="Company Name" href="/derivatives/SLUG-futures">
const regex = /<a title="([^"]+)" href="\/derivatives\/([a-z0-9&-]+)-futures">/gi;

const results = [];
const seen = new Set();

let match;
while ((match = regex.exec(html)) !== null) {
  const name = match[1]
    .replace(/&amp;/g, '&')
    .trim();
  const slug = match[2];

  // Derive symbol from slug: uppercase, remove trailing "-futures" already stripped
  const symbol = slug.toUpperCase();

  if (!seen.has(symbol)) {
    seen.add(symbol);
    results.push({ json: { name, symbol } });
  }
}

return results;

