const items = $input.all();

let advances = 0, declines = 0, unchanged = 0;

items.forEach(item => {
  const json = item.json || {};

  // Skip if no symbol (empty row)
  if (!json.Symbol) return;

  // Access "Change %" with bracket notation because of the space
  const changePct = Number(json['Change %'] ?? json.change_pct ?? 0);

  if (changePct > 0.01) advances++;
  else if (changePct < -0.01) declines++;
  else unchanged++;
});

const total = advances + declines + unchanged;
const adRatio = declines > 0 ? Number((advances / declines).toFixed(2)) : (advances || 0);

return [{
  json: {
    advances,
    declines,
    unchanged,
    total_stocks: total,
    ad_ratio: adRatio,
    advance_percent: total > 0 ? Number(((advances / total) * 100).toFixed(2)) : 0,
    decline_percent: total > 0 ? Number(((declines / total) * 100).toFixed(2)) : 0,
    sample_size: "NIFTY 50 via Google Sheets",
    updated_at: new Date().toISOString()
  }
}];

// Get all rows from the HTTP node
const rows = $input.all().map(item => item.json);

const byDate = {};

for (const row of rows) {
  if (!row.date) continue;

  if (!byDate[row.date]) {
    byDate[row.date] = {
      date: row.date,
      fiiNet: 0,
      diiNet: 0
    };
  }

  // Parse string numbers (handles "15,241.39" and "-936.14")
  const netStr = String(row.netValue || '0').replace(/,/g, '');
  const net = parseFloat(netStr) || 0;

  const cat = String(row.category || '').toUpperCase();

  // "FII/FPI" → FII, "DII" → DII
  if (cat.includes('FII')) {
    byDate[row.date].fiiNet = net;
  } else if (cat.includes('DII')) {
    byDate[row.date].diiNet = net;
  }
}

// Sort by date, keep last 5 days
const result = Object.values(byDate)
  .sort((a, b) => new Date(a.date) - new Date(b.date))
  .slice(-5);

// Return in n8n item format
return result.map(item => ({ json: item }));

